const body = $input.first().json.body ?? $input.first().json;

// ── Autenticação ─────────────────────────────────────────────────────────────
const token         = $input.first().json.headers?.['x-webhook-token']
                   ?? $input.first().json.headers?.['X-Webhook-Token']
                   ?? '';
const expectedToken = $env.WEBHOOK_TOKEN ?? '';
if (expectedToken && token !== expectedToken) {
  throw new Error('Token inválido — acesso não autorizado');
}

// ── Validação de campos obrigatórios ─────────────────────────────────────────
if (!body.nome || !body.whatsapp) {
  throw new Error('Campos obrigatórios ausentes: nome, whatsapp');
}

// ── Normalização básica ───────────────────────────────────────────────────────
const whatsapp   = String(body.whatsapp).replace(/\D/g, '');
const score      = typeof body.score === 'number' ? body.score : 0;
const score_max  = typeof body.score_max === 'number' ? body.score_max : 0;
const cta_origem = body.cta_origem ?? 'formulario';

// ── Classificação: cada formulário envia o seu próprio valor ──────────────────
//
// PRINCÍPIO: o formulário conhece suas próprias perguntas e pesos — ele é
// responsável por calcular e enviar `classificacao`. O workflow apenas valida.
//
// Se `classificacao` vier preenchido e válido → usa diretamente.
// Se vier ausente ou inválido → calcula fallback via score percentual
//   usando score_max (máximo possível do formulário de origem).
//
// Isso garante que um formulário GMN (max 6 pts) e um formulário geral
// (max 17 pts) sejam tratados com os thresholds corretos.

const CLASSIFICACOES_VALIDAS = new Set([
  'ULTRA_QUENTE', 'QUENTE', 'MORNO', 'FRIO', 'NAO_QUALIFICADO'
]);

let classificacao = body.classificacao ?? null;

if (!classificacao || !CLASSIFICACOES_VALIDAS.has(classificacao)) {
  // Fallback: calcula pela porcentagem do score em relação ao máximo do formulário
  if (score_max > 0) {
    const pct = score / score_max;
    if      (pct >= 0.88) classificacao = 'ULTRA_QUENTE';  // >= 88%
    else if (pct >= 0.65) classificacao = 'QUENTE';        // >= 65%
    else if (pct >= 0.35) classificacao = 'MORNO';         // >= 35%
    else if (pct >= 0.15) classificacao = 'FRIO';          // >= 15%
    else                  classificacao = 'NAO_QUALIFICADO';
  } else {
    // sem score_max e sem classificacao → não qualificado
    classificacao = 'NAO_QUALIFICADO';
  }
  console.log(`[Universal] Classificacao ausente/inválida — fallback por score percentual: ${score}/${score_max} → ${classificacao}`);
}

// ── Prioridade derivada da classificação ──────────────────────────────────────
const prioMap = {
  ULTRA_QUENTE: 'urgente',
  QUENTE:       'alta',
  MORNO:        'media',
  FRIO:         'baixa',
  NAO_QUALIFICADO: 'baixa',
};
const prioridade = body.prioridade ?? prioMap[classificacao] ?? 'baixa';

// ── Montar detalhes_funil ────────────────────────────────────────────────────
// Campo livre `funil` recebe qualquer dado do formulário.
// Campo `agendamento` é normalizado para sub-objeto padronizado.
const funil       = body.funil ?? {};
const agendamento = body.agendamento ?? null;

const detalhes_funil = {
  cta_origem,
  ...funil,
  ...(agendamento ? { agendamento } : {}),
};

// ── Retornar payload normalizado ─────────────────────────────────────────────
return [{ json: {
  // identidade
  nome:         body.nome.trim(),
  whatsapp,
  email:        body.email   || '',
  empresa:      body.empresa || body.nome.trim(),
  cidade:       body.cidade  || '',

  // classificação (já validada/calculada acima)
  classificacao,
  score,
  score_max,
  prioridade,

  // origem
  fonte:        body.fonte        || 'formulario',
  servico:      body.servico      || '',
  utm_source:   body.utm_source   || '',
  utm_medium:   body.utm_medium   || '',
  utm_campaign: body.utm_campaign || '',

  // comportamento
  cta_origem,

  // funil
  detalhes_funil,

  // timestamp
  recebido_em: body.data || new Date().toISOString(),
} }];

const lead     = $('Validar e Normalizar Payload').first().json;
const result   = $input.first().json;
const existing = Array.isArray(result) ? result[0] : null;

// ── Regras de decisão ────────────────────────────────────────────────────────
//
// Lead NÃO existe → INSERT sempre
//
// Lead EXISTE:
//   cta_origem = 'whatsapp'    → UPDATE: registra que o próprio lead iniciou contato
//   cta_origem = 'agendamento' → IGNORAR: agendamento duplicado (lead já registrado)
//   cta_origem = 'formulario'  → IGNORAR: reenvio do formulário
//   qualquer outro             → IGNORAR por segurança

let acao;
if (!existing) {
  acao = 'inserir';
} else if (lead.cta_origem === 'whatsapp') {
  acao = 'atualizar_contato';
} else {
  acao = 'ignorar';
  console.log(`[Universal] Lead duplicado ignorado: ${lead.nome} (${lead.whatsapp}) cta=${lead.cta_origem} — já existe como ${existing.id}`);
}

return [{ json: {
  ...lead,
  acao,
  lead_id_existente: existing?.id ?? null,
} }];

