const input  = $input.first()?.json ?? {};
const lead   = $('Decidir Ação').first().json;

const record   = Array.isArray(input) ? input[0] : input;
const leadId   = record?.id ?? lead.lead_id_existente ?? null;
const operacao = lead.acao === 'inserir'           ? 'INSERT'
               : lead.acao === 'atualizar_contato' ? 'UPDATE'
               : 'IGNORADO';

if (lead.acao !== 'ignorar' && !leadId) {
  console.error(`[Universal] Falha no ${operacao}:`, JSON.stringify(input));
} else {
  console.log(
    `[Universal] ${operacao}: ${leadId ?? '—'}`,
    `| ${lead.nome} (${lead.whatsapp})`,
    `| fonte=${lead.fonte}`,
    `| cta=${lead.cta_origem}`,
    `| class=${lead.classificacao}`,
    `| score=${lead.score}/${lead.score_max || '?'}`,
  );
}

return [{ json: { success: lead.acao === 'ignorar' || !!leadId, lead_id: leadId, operacao } }];
